using Microsoft.Win32; using System; using System.IO; using System.Windows; namespace EtoDesktop { public partial class MainWindow : Window { private string path; private string type; private DesktopLayer layer=new DesktopLayer(); public MainWindow(){InitializeComponent();} private void Pick(string filter){var d=new OpenFileDialog{Filter=filter}; if(d.ShowDialog()==true){path=d.FileName; var e=Path.GetExtension(path).ToLowerInvariant(); type=e==".gif"?"gif":(e==".mp4"||e==".wmv"||e==".avi"||e==".mpg"||e==".mpeg"?"video":"image"); BackgroundLabel.Text=Path.GetFileName(path);}} private void Image_Click(object s,RoutedEventArgs e){Pick("Images|*.png;*.jpg;*.jpeg;*.bmp");} private void Gif_Click(object s,RoutedEventArgs e){Pick("GIF|*.gif");} private void Video_Click(object s,RoutedEventArgs e){Pick("Video|*.mp4;*.wmv;*.avi;*.mpg;*.mpeg");} private void Apply_Click(object s,RoutedEventArgs e){layer.Apply(path,type,TaskbarEnabled.IsChecked==true,ClockEnabled.IsChecked==true);StatusText.Text="تم التطبيق";} private void Close_Click(object s,RoutedEventArgs e){layer.Restore();Close();}}}